const generateId = () => Math.random().toString(36).substring(2, 15)

class WatsWalletProvider {
  constructor() {
    this.isWatsWallet = true
    this.isMetaMask = true
    this._callbacks = new Map()
    // on() her callback icin bir sarmalayici kaydeder; removeListener'in AYNI
    // sarmalayiciyi sokebilmesi icin esleme burada tutulur. Esleme olmadan
    // removeEventListener(orijinal callback) sessiz bir no-op olur ve her
    // yeniden abonelikte isleyiciler katlanir.
    this._listenerWrappers = new Map()
    // EIP-1193 baglanti durumu. Sayfa yuklendiginde TRUE: uzanti enjekte
    // edildiyse saglayici istek alabilir durumdadir ve bugune kadarki
    // davranis (kosulsuz `return true`) budur. Yalnizca background ACIKCA
    // 'disconnect' yayinlarsa false olur, 'connect' ile geri doner.
    this._connected = true

    window.addEventListener("message", (event) => {
      if (event.source !== window || !event.data || event.data.target !== 'wats_inpage') return

      const { id, result, error, method } = event.data
      // 'disconnect': EIP-1193 event, background zincir EVM olmaktan cikinca
      // (Solana aktif oldugunda) yayinlar -- saglayici hicbir EVM zincirine bagli
      // degil ama uzantinin kendisi hala orada (code 4901, Chain Disconnected).
      // 'connect': AYNI YUZEYIN DIGER UCU -- kullanici bir EVM zincirine GERI
      // dondugunde yayilir. Yalnizca 'chainChanged' yetmez: wagmi/viem'in
      // injected connector'u onDisconnect'te durumunu temizler ve
      // onChainChanged yalnizca HALA BAGLIYSA is yapar.
      if (method === 'accountsChanged' || method === 'chainChanged' || method === 'disconnect' || method === 'connect') {
        // Durum olaydan ONCE guncellenir: dinleyici geri cagriminin ICINDE
        // isConnected() sorarsa (wagmi/viem connector'lari bunu yapar) yanit
        // az once bildirilen gercegi yansitmali.
        if (method === 'disconnect') this._connected = false
        if (method === 'connect') this._connected = true
        window.dispatchEvent(new CustomEvent(`ethereum_${method}`, { detail: result }))
        return
      }

      if (id && this._callbacks.has(id)) {
        const { resolve, reject } = this._callbacks.get(id)
        this._callbacks.delete(id)
        if (error) {
          // EIP-1193 hata KODU korunmali: wagmi/viem/ethers 4001'i (kullanici
          // reddi) ve 4901'i (zincir kopuk) Error.code uzerinden tanir. Kod
          // dusurulurse her red, beklenmedik cuzdan arizasi gibi gorunur.
          const err = new Error((error && error.message) || error)
          if (error && typeof error === 'object') {
            if (error.code !== undefined) err.code = error.code
            if (error.data !== undefined) err.data = error.data
          }
          reject(err)
        }
        else resolve(result)
      }
    })
  }

  async request({ method, params = [] }) {
    return new Promise((resolve, reject) => {
      const id = generateId()

      this._callbacks.set(id, { resolve, reject })

      window.postMessage({
        target: 'wats_content_script',
        id: id,
        payload: {
          method: method,
          params: params
        }
      }, "*")
    })
  }

  on(eventName, callback) {
    let wrappers = this._listenerWrappers.get(eventName)
    if (!wrappers) {
      wrappers = new Map()
      this._listenerWrappers.set(eventName, wrappers)
    }
    let wrapper = wrappers.get(callback)
    if (!wrapper) {
      wrapper = (e) => callback(e.detail)
      wrappers.set(callback, wrapper)
    }
    // Ayni (olay, callback) cifti icin ayni sarmalayici kullanilir;
    // addEventListener ayni referansi ikinci kez EKLEMEZ, isleyici katlanmaz.
    window.addEventListener(`ethereum_${eventName}`, wrapper)
  }

  removeListener(eventName, callback) {
    const wrappers = this._listenerWrappers.get(eventName)
    const wrapper = wrappers && wrappers.get(callback)
    if (!wrapper) return
    window.removeEventListener(`ethereum_${eventName}`, wrapper)
    wrappers.delete(callback)
  }

  // EIP-1193: saglayici bir zincire baglanabilir durumda mi. Sabit `true`
  // ARTIK DOGRU DEGIL: background Solana'ya gecisde 'disconnect' (4901)
  // yayinliyor. Ayni yuzeyin bir yarisini dogru, digerini sabit birakmak
  // dapp'e CELISKILI iki cevap verirdi -- olay 'baglanti kesildi' derken
  // isConnected() 'bagliyim' der.
  isConnected() {
    return this._connected
  }
}

const provider = new WatsWalletProvider()

// SAVUNMACI YAZIM: tonInjected.js AYNI nesneye `tonconnect` alanini yaziyor ve
// iki MAIN-world betigin yuklenme sirasina GUVENILMEZ. Duz atama, TON kopruyu
// sessizce silebilirdi -- dapp cuzdani bulamaz, hata da gorunmez.
const existingWats = window.wats
window.wats = provider
if (existingWats && existingWats.tonconnect) window.wats.tonconnect = existingWats.tonconnect
// UCUNCU SERIT: solanaInjected.js AYNI nesneye `solana` alanini yaziyor. Bu satir
// olmadan injected.js SONRA yuklendiginde Solana koprusu sessizce silinir ve dapp
// cuzdani Wallet Standard listesinde goremez.
if (existingWats && existingWats.solana) window.wats.solana = existingWats.solana
if (!window.ethereum) {
  window.ethereum = provider
}

window.dispatchEvent(new Event("ethereum#initialized"))

// EIP-6963: uuid sayfa oturumu boyunca SABIT olmali. Her duyuruda yeni uuid
// uretmek, uuid ile anahtarlayan cuzdan secicilerinde ayni cuzdani coklar ve
// sectigi uuid'yi saklayan dapp'in otomatik yeniden baglanmasini bozar.
const providerUuid = crypto.randomUUID()

const announceProvider = () => {
  window.dispatchEvent(new CustomEvent('eip6963:announceProvider', {
    detail: Object.freeze({
      info: {
        uuid: providerUuid,
        name: 'WATS Wallet',
        icon: 'data:image/png;base64,',
        rdns: 'io.wats.wallet'
      },
      provider: provider
    })
  }))
}

window.addEventListener('eip6963:requestProvider', announceProvider)
announceProvider()